static void cancel_att_send_op(struct att_send_op *op)
{
	void *user_data;
	void (*destroy)(void *);

	if (!op)
		return;

	/*
	 * Detach the callback state from the operation *before* invoking
	 * the destroy handler.  The handler is untrusted code and may free
	 * `op` itself, or re-enter this function (directly or indirectly)
	 * through the operation's callback.  Clearing the fields first
	 * guarantees that:
	 *   1. no use-after-free writes occur after `destroy` returns if it
	 *      released `op`, and
	 *   2. a re-entrant call observes a cancelled operation and becomes a
	 *      no-op, so `destroy` can never run twice for the same op.
	 */
	destroy = op->destroy;
	user_data = op->user_data;

	op->user_data = NULL;
	op->callback = NULL;
	op->destroy = NULL;

	if (destroy)
		destroy(user_data);
}

