        for (;;) {
            const CString::size_type uSep =
                sModPath.find_first_of("/\\", uStart);
            const CString sPart = (uSep == CString::npos)
                                      ? sModPath.substr(uStart)
                                      : sModPath.substr(uStart, uSep - uStart);
            if (sPart.empty() || sPart == "." || sPart == "..") {
                // empty component means a doubled/leading separator
                return true;
