int crxFreeImageData(CrxImage *img)
{
  CrxTile *tile;
  long long nTiles;

  if (!img)
    return 0;

  tile = img->tiles;

  /* Compute the tile count in a wider type and reject values that do not fit
     in an int, avoiding signed overflow (undefined behavior) and a subsequent
     out-of-bounds iteration over the tile array. */
  nTiles = (long long)img->tileRows * (long long)img->tileCols;
  if (nTiles < 0 || nTiles > (long long)INT_MAX)
    nTiles = 0;

  if (tile)
  {
    /* Index the array directly; do not advance `tile` as well, otherwise the
       loop reads past the end of the allocated tile array. */
    for (long long curTile = 0; curTile < nTiles; curTile++)
      if (tile[curTile].comps)
        for (int32_t curPlane = 0; curPlane < img->nPlanes; curPlane++)
          crxFreeSubbandData(img, tile[curTile].comps + curPlane);
    free(tile);
    img->tiles = 0;
  }

  if (img->planeBuf)
  {
    free(img->planeBuf);
    img->planeBuf = 0;
  }

  return 0;
}

